package main

import "fmt"

func main() {
	fmt.Println(7 / 2)     // 3   (int division truncates)
	fmt.Println(7.0 / 2)   // 3.5 (float division)
	fmt.Println(-7 % 3)    // -1  (sign follows dividend)
	fmt.Println(7 % -3)    // 1
}
// Output:
// 3
// 3.5
// -1
// 1

