import "fmt"

func check(name string, v bool) bool {
	fmt.Println("evaluating", name)
	return v
}

func main() {
	// Left is false, so the right side is never evaluated.
	if check("left", false) && check("right", true) {
		fmt.Println("both true")
	}
	fmt.Println("---")
	// Left is true, so || skips the right side.
	if check("a", true) || check("b", true) {
		fmt.Println("at least one true")
	}
}

