package solution

import "testing"

func TestIsPowerOfTwo(t *testing.T) {
	cases := []struct {
		in   int
		want bool
	}{
		{1, true},
		{2, true},
		{8, true},
		{1024, true},
		{0, false},
		{3, false},
		{6, false},
		{-8, false},
	}
	for _, c := range cases {
		if got := IsPowerOfTwo(c.in); got != c.want {
			t.Errorf("IsPowerOfTwo(%d)=%v want %v", c.in, got, c.want)
		}
	}
}

