func ComputeRate(hits, total int) float64 {
	return float64(hits) / float64(total) // float division: 3.0 / 4.0
}
// ComputeRate(3, 4) -> 0.75

func CountSetBits(n uint) int {
	count := 0
	for n != 0 {
		n &= n - 1 // clear the lowest set bit
		count++
	}
	return count
}

func SafeDivide(a, b int) (int, bool) {
	// Guard first: b != 0 is evaluated before we ever divide.
	if b != 0 {
		return a / b, true // integer division truncates toward zero
	}
	return 0, false // signal invalid input instead of panicking
}
